def atlas():
 cards=[]; details=[]
 for i,(name,cat,label,summary,stack,case,repo,detail) in enumerate(ARCHIVE):
  source=f'https://github.com/A101shah/{repo}' if repo else None
  destination=f'projects/{case}.html' if case else source
  action=f'<a class="text-link" href="{destination}"'+(' target="_blank" rel="noopener noreferrer"' if not case else '')+f'>{"Read case study" if case else "Explore source"} ↗</a>' if destination else '<span class="source-note">Public source link coming later.</span>'
  cards.append(f'''<article class="atlas-card" data-atlas-category="{cat}" data-search="{escape((name+' '+label+' '+stack).lower())}"><span class="atlas-number">{i+1:02d}</span><div><span class="atlas-category">{label}</span><h3>{escape(name)}</h3><p>{escape(summary)}</p><span class="atlas-stack">{escape(stack)}</span></div><button class="atlas-open" data-project="{i}" type="button" aria-label="Explore {escape(name)}">↗</button><details class="atlas-inline"><summary>Project notes</summary><p>{escape(detail)}</p>{action}</details></article>''')
  details.append(dict(name=name,label=label,summary=summary,stack=stack,detail=detail,source=source,case=f'projects/{case}.html' if case else None))
 (ROOT/'dist/assets/projects.js').write_text('window.portfolioProjects = '+json.dumps(details,ensure_ascii=False)+';\n')
 return '''<section id="atlas" class="atlas-section section-shell"><div class="section-heading"><div><div class="eyebrow">02 / PROJECT ATLAS</div><h2>One curiosity.<br>Many directions.</h2></div><p>A wider view of my work.<br>From learning experiments to application prototypes.</p></div><div class="atlas-tools"><label class="atlas-search"><span aria-hidden="true">⌕</span><span class="sr-only">Search projects</span><input id="project-search" type="search" placeholder="Search projects, tools, ideas…" autocomplete="off"></label><div class="atlas-filters" role="group" aria-label="Filter project atlas"><button data-atlas-filter="all" aria-pressed="true">All <small>13</small></button><button data-atlas-filter="ai" aria-pressed="false">AI & vision</button><button data-atlas-filter="data" aria-pressed="false">Data & math</button><button data-atlas-filter="web" aria-pressed="false">Apps & systems</button></div></div><p class="atlas-count" id="atlas-count" role="status">13 projects to explore</p><div class="atlas-grid">'''+''.join(cards)+'''</div><div class="atlas-empty" hidden><h3>No projects in this orbit.</h3><p>Try another keyword or show all projects.</p><button id="clear-search" class="button primary" type="button">Reset search</button></div><p class="archive-note">Project notes draw on my original portfolio. Source links are provided where available; prototypes and explorations are not presented as verified production deployments.</p></section><dialog id="project-dialog" aria-labelledby="dialog-title"><button class="dialog-close" aria-label="Close project details" type="button">✕</button><span id="dialog-label" class="eyebrow"></span><h2 id="dialog-title"></h2><p id="dialog-summary" class="dialog-lead"></p><p id="dialog-detail"></p><div id="dialog-stack" class="tags"></div><div id="dialog-actions"></div></dialog>'''

